// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Reentrance c;

    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        // Keep amount in a wide but meaningful range: a positive deposit that won't overflow
        amount = bound(amount, 1, type(uint128).max);

        // Adversarial recipient: reverts on every call, so the external call from
        // withdrawBalance() fails. The reference must revert; the mutant must not.
        Reverter reverter = new Reverter();

        // Give the reverter a positive balance by depositing through the reference.
        vm.deal(address(reverter), amount);
        vm.prank(address(reverter));
        c.addToBalance{value: amount}();

        uint256 contractBalanceBefore = address(c).balance;
        uint256 reverterBalanceBefore = c.getBalance(address(reverter));

        // The reverter is the caller; the reference's withdrawBalance() will
        // attempt to pay it and the fallback will revert. The reference must
        // propagate that revert; the mutant swallows it.
        vm.prank(address(reverter));
        bool ok;
        try c.withdrawBalance() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: if the payout to the caller fails, the transaction must
        // not succeed AND the contract must retain the ETH it was holding.
        // The reference satisfies this for every input; the mutant violates it
        // whenever the reverter has a deposit.
        assertTrue(
            (!ok && address(c).balance == contractBalanceBefore && c.getBalance(address(reverter)) == reverterBalanceBefore)
        );
    }
}

contract Reverter {
    fallback() external payable { revert(); }
    receive() external payable { revert(); }
}
